-- DA (Disbursement Account) rate tables, ported from the LBH Curacao Excel sheet.
-- Editable in the dashboard like the existing PDA config tables.

create table if not exists public.da_pilotage_tariffs (id bigserial primary key, gt_min numeric, gt_max numeric, pilotage_ang numeric, hc_surcharge_ang numeric, is_active boolean default true, created_at timestamptz default now());
create table if not exists public.da_towage_tariffs (id bigserial primary key, gt_min numeric, gt_max numeric, tariff_a numeric, is_active boolean default true, created_at timestamptz default now());
create table if not exists public.da_linesmen_tariffs (id bigserial primary key, gt_min numeric, gt_max numeric, amount numeric, is_active boolean default true, created_at timestamptz default now());
create table if not exists public.da_settings (key text primary key, value numeric, description text, updated_at timestamptz default now());

alter table public.da_pilotage_tariffs enable row level security;
create policy "authenticated_read" on public.da_pilotage_tariffs for select to authenticated using (true);
create policy "service_role_all" on public.da_pilotage_tariffs for all to service_role using (true) with check (true);
alter table public.da_towage_tariffs enable row level security;
create policy "authenticated_read" on public.da_towage_tariffs for select to authenticated using (true);
create policy "service_role_all" on public.da_towage_tariffs for all to service_role using (true) with check (true);
alter table public.da_linesmen_tariffs enable row level security;
create policy "authenticated_read" on public.da_linesmen_tariffs for select to authenticated using (true);
create policy "service_role_all" on public.da_linesmen_tariffs for all to service_role using (true) with check (true);
alter table public.da_settings enable row level security;
create policy "authenticated_read" on public.da_settings for select to authenticated using (true);
create policy "service_role_all" on public.da_settings for all to service_role using (true) with check (true);

truncate public.da_pilotage_tariffs, public.da_towage_tariffs, public.da_linesmen_tariffs;
